 try{
  await saveCurrent();
  const records=await storeOp('designs','readonly',s=>s.getAll());
  const existing=records.find(r=>!r.recoveryBackup&&r.config.renderer==='sekar'&&r.config.preset===key&&!sekarSource(r.config));
  if(existing){await loadDesign(existing);return;}
  state=merge(clone(INITIAL),{renderer:'sekar',preset:key,theme:clone(PRESETS[key].theme),assets:{base:PRESETS[key].assets.base}});
  designId=crypto.randomUUID();designName='Sekar '+(key==='sage'?'Sage':'Prada');
  $('#design-name').value=designName;resetHistory();await saveCurrent();post();render();navigateSection('cover');
  toast(designName+' is ready to edit.');
 }catch(e){showStorageError();}
