// Recognize the old switch bug only when the collection's artwork and photo
// folder agree. Custom Sekar artwork alone must never trigger recovery.
function sekarSource(config){
 if(config.renderer!=='sekar'||!['sage','prada'].includes(config.preset))return null;
 return Object.entries(COLLECTION_DESIGNS).find(([,design])=>{
  const assets=design.config.assets;
  return config.assets?.base===PRESETS[config.preset].assets.base&&
   config.assets.photosBase===assets.photosBase&&assets.photosBase!==INITIAL.assets.photosBase&&
   Object.keys(SLOT_NAMES).filter(k=>assets[k]&&config.assets[k]===assets[k]&&assets[k]!==INITIAL.assets[k]).length>=3;
 });
}
async function recoverSekarSwitch(record){
 const source=!record.recoveryBackup&&sekarSource(record.config);
 if(!source)return record;
 await storeOp('designs','readwrite',s=>s.put({...clone(record),id:crypto.randomUUID(),name:record.name+' (before preview repair)',recoveryBackup:true,updated:Date.now()}));
 const [renderer,design]=source,config=clone(record.config);
 config.renderer=renderer;config.assets.base=design.config.assets.base;
 config.theme=clone(design.config.theme);config.preset=design.config.preset;
 const repaired={...record,config,updated:Date.now()};
 await storeOp('designs','readwrite',s=>s.put(repaired));
 return repaired;
}
