function storeOp(store,mode,fn){return new Promise((resolve,reject)=>{if(!db)return reject(Error('Storage unavailable'));const tx=db.transaction(store,mode),r=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(r?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage write interrupted'));});}
