async function fetchText(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('Unable to load '+url+' ('+r.status+').');return r.text();}
async function toDataURL(src){if(!src||src.startsWith('data:'))return src;const url=new URL(src,new URL('template/',location.href));const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('Unable to embed artwork: '+src);const blob=await r.blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});}
