let previewWidth=390;
function fitPreview(){
 const area=$('.preview-scroll'),device=$('#device'),fit=$('#preview-fit'),padding=getComputedStyle(area);
 const availableWidth=area.clientWidth-parseFloat(padding.paddingLeft)-parseFloat(padding.paddingRight);
 const availableHeight=area.clientHeight-parseFloat(padding.paddingTop)-parseFloat(padding.paddingBottom);
 if(availableWidth<=0||availableHeight<=0)return;
 const height=780,width=previewWidth,scale=Math.min(1,availableWidth/(width+14),availableHeight/(height+14));
 device.style.width=width+'px';device.style.height=height+'px';frame.style.width=width+'px';frame.style.height=height+'px';device.style.transform='scale('+scale+')';
 fit.style.width=((width+14)*scale)+'px';fit.style.height=((height+14)*scale)+'px';
 $('#canvas-size').textContent=width+' × '+height+(width===390?' · 9:18':' · Wide');
}
new ResizeObserver(fitPreview).observe($('.preview-scroll'));
fitPreview();
